import * as React from "react"
import { AnimatePresence } from "motion/react"
import {
  BrainIcon,
  ChartColumnIcon,
  CodeIcon,
  FileTextIcon,
  GlobeIcon,
  MinusIcon,
  PenLineIcon,
  SquarePenIcon,
} from "lucide-react"
import { getToolName, isToolUIPart } from "ai"

import { cn } from "@/lib/utils"
import { getMessageText } from "@/lib/ai"
import { AgentOrb } from "@/components/ds/agent-orb"
import { ModelIcon } from "@/components/ds/model-icons"
import { Widget, WidgetHeader, WidgetPanel, WidgetTitle } from "@/components/ds/widget"
import { Button } from "@/components/ui/button"
import { Tooltip, TooltipContent, TooltipTrigger } from "@/components/ui/tooltip"
import { AttachmentChip, AttachmentPreview } from "@/components/parts/attachment"
import { ConnectPrompt, type ConnectState } from "@/components/parts/connect-prompt"
import { ChatError } from "@/components/chat/chat-error"
import { ChatPill } from "@/components/chat/chat-pill"
import { ChatEmpty, ChatSuggestion } from "@/components/chat/chat-empty"
import { ChatThread, ChatThreadItem } from "@/components/chat/chat-thread"
import { ChatTurn } from "@/components/chat/chat-turn"
import {
  Composer,
  ComposerAttach,
  ComposerAttachments,
  ComposerInput,
  ComposerMic,
  ComposerModelSelect,
  ComposerSubmit,
  ComposerToggle,
  ComposerToolbar,
} from "@/components/chat/composer"
import { useAgentChat } from "@/components/chat/use-agent-chat"
import {
  CHAINED_CONTINUATION_ID,
  failOnce,
  FILES,
  SCENARIOS,
  transports,
  type ChatMessage,
  type ScenarioKey,
} from "@/examples/assistant/scripts"
import { data, tools } from "@/examples/assistant/tools"

// The playground's assistant: nothing here but composition of the chat kit
// (components/chat) with the demo's tools and scripted conversations.

const SCENARIO_ICONS = { globe: GlobeIcon, pen: PenLineIcon, code: CodeIcon, chart: ChartColumnIcon, file: FileTextIcon }

const MODELS = {
  claude: { name: "Claude", provider: "Anthropic", icon: <ModelIcon family="claude" /> },
  gpt: { name: "GPT", provider: "OpenAI", icon: <ModelIcon family="openai" /> },
  gemini: { name: "Gemini", provider: "Google", icon: <ModelIcon family="gemini" /> },
  llama: { name: "Llama", provider: "Meta", icon: <ModelIcon family="meta" /> },
  grok: { name: "Grok", provider: "xAI", icon: <ModelIcon family="grok" /> },
}

export type AssistantLayout = "widget" | "full"

export function Assistant({
  layout = "widget",
  initialScenario,
}: {
  layout?: AssistantLayout
  /** Start straight into a scripted scenario instead of the empty state. */
  initialScenario?: ScenarioKey
}) {
  const [scenario, setScenario] = React.useState<ScenarioKey>(initialScenario ?? "draft")
  const [run, setRun] = React.useState(0)
  const [started, setStarted] = React.useState(Boolean(initialScenario))

  return (
    <Session
      key={`${scenario}-${run}`}
      layout={layout}
      scenario={scenario}
      autoStart={started}
      onPick={(key) => {
        setScenario(key)
        setStarted(true)
        setRun((r) => r + 1)
      }}
      onReset={() => {
        setStarted(false)
        setRun((r) => r + 1)
      }}
    />
  )
}

function Session({
  layout,
  scenario,
  autoStart,
  onPick,
  onReset,
}: {
  layout: AssistantLayout
  scenario: ScenarioKey
  autoStart: boolean
  onPick: (key: ScenarioKey) => void
  onReset: () => void
}) {
  const script = SCENARIOS[scenario].chat
  // One overloaded request in the metrics scenario, to show the error line.
  const [transport] = React.useState(() =>
    failOnce(transports[scenario], "Translate", "The model is over capacity right now. Nothing was sent.")
  )
  const chat = useAgentChat<ChatMessage>({
    messages: script.get(0),
    transport,
    tools,
  })
  const { messages, sendMessage, setMessages, busy, waiting } = chat
  const [model, setModel] = React.useState<keyof typeof MODELS>("claude")
  const [search, setSearch] = React.useState(true)
  const [think, setThink] = React.useState(true)
  const [minimised, setMinimised] = React.useState(false)

  // A client tool answered outside the transcript: Connect docks above the
  // composer while the turn waits on it, then says what happens next.
  const connect = useConnect(messages, (toolCallId, connected) =>
    chat.addToolOutput({ tool: "connectApp", toolCallId, output: { connected } } as never)
  )

  const next = script.next(messages)
  const send = () => {
    if (next && !busy && !waiting) void sendMessage(next)
  }
  useScriptedSession({ autoStart, next, messages, busy, sendMessage, setMessages })

  const full = layout === "full"

  // Two header actions, both real: start over, and get out of the way.
  const header = (
    <>
      <AgentOrb phase={chat.phase} />
      <WidgetTitle>Assistant</WidgetTitle>
      <span className="ml-auto flex items-center gap-0.5">
        <HeaderAction label="New chat" onClick={onReset} disabled={messages.length === 0}>
          <SquarePenIcon />
        </HeaderAction>
        <HeaderAction label="Minimise" onClick={() => setMinimised(true)}>
          <MinusIcon />
        </HeaderAction>
      </span>
    </>
  )

  const column = full ? "mx-auto w-full max-w-[720px]" : ""

  const conversation =
    messages.length === 0 ? (
      <ChatEmpty title="Good evening" description="What are we working on?" size={full ? "lg" : "default"}>
        {(Object.keys(SCENARIOS) as ScenarioKey[]).map((key) => {
          const Icon = SCENARIO_ICONS[SCENARIOS[key].icon]
          return (
            <ChatSuggestion key={key} icon={<Icon />} onClick={() => onPick(key)}>
              {SCENARIOS[key].label}
            </ChatSuggestion>
          )
        })}
      </ChatEmpty>
    ) : (
      <ChatThread busy={busy} className={cn(full && cn(column, "px-6 py-10"))}>
        {messages.map((message, index) => (
          <ChatThreadItem key={index} message={message}>
            <ChatTurn
              message={message}
              tools={tools}
              data={data}
              renderFile={(f) => <FileChip name={f.filename ?? "file"} />}
              onRegenerate={
                index === messages.length - 1 && !busy ? () => void chat.regenerate() : undefined
              }
              phase={chat.phase}
              active={index === chat.activeIndex}
              streaming={busy && index === messages.length - 1}
              pending={waiting && index === messages.length - 1}
              onToolOutput={(tool, toolCallId, output) =>
                chat.addToolOutput({ tool, toolCallId, output } as never)
              }
              onApproval={(id, approved) => chat.addToolApprovalResponse({ id, approved })}
            />
          </ChatThreadItem>
        ))}
        {chat.error && (
          <ChatError
            message={chat.error.message}
            retryLabel={model === "gpt" ? "Retry" : "Retry with GPT"}
            onRetry={() => {
              setModel("gpt")
              void chat.regenerate()
            }}
          />
        )}
      </ChatThread>
    )

  const ready = Boolean(next) && !waiting && !busy
  const nextFiles = ready ? (next?.parts.filter((p) => p.type === "file") ?? []) : []
  const composer = (
    <Composer onSubmit={send}>
      <ComposerAttachments>
        {nextFiles.map((f) => (
          <FileChip key={f.url} name={f.filename ?? "file"} />
        ))}
      </ComposerAttachments>
      <ComposerInput
        readOnly
        aria-label="Next scripted message"
        value={ready && next ? getMessageText(next) : ""}
        placeholder={
          connect.pending ? "Connect Slack above to continue…" : waiting ? "Answer above to continue…" : "Ask anything…"
        }
      />
      <ComposerToolbar>
        <ComposerAttach />
        <ComposerToggle icon={<GlobeIcon />} pressed={search} live={chat.phase === "searching"} onPressedChange={setSearch}>
          Search
        </ComposerToggle>
        <ComposerToggle icon={<BrainIcon />} pressed={think} live={chat.phase === "thinking"} onPressedChange={setThink}>
          Think
        </ComposerToggle>
        <ComposerModelSelect models={MODELS} value={model} onValueChange={setModel} />
        <ComposerMic className="ml-auto" />
        <ComposerSubmit busy={busy} onStop={chat.stop} disabled={!next || waiting} />
      </ComposerToolbar>
    </Composer>
  )

  if (full) {
    return (
      <div data-slot="assistant-page" className="flex h-svh w-full flex-col bg-background">
        {/* pr-16 leaves room for the playground's theme toggle */}
        <header className="flex h-16 shrink-0 items-center gap-2 border-b border-border/70 pr-16 pl-5">
          {header}
        </header>
        <div className="relative min-h-0 flex-1">{conversation}</div>
        <div className={cn(column, "flex shrink-0 flex-col gap-2 px-6 pb-6")}>
          <AnimatePresence>{connect.prompt}</AnimatePresence>
          <div className="rounded-2xl border border-border bg-card shadow-xs">{composer}</div>
        </div>
      </div>
    )
  }

  return (
    <AnimatePresence mode="wait" initial={false}>
      {minimised ? (
        <ChatPill key="pill" phase={chat.phase} onOpen={() => setMinimised(false)} />
      ) : (
        <Widget key="panel" className="w-full max-w-[620px]">
          <WidgetHeader>{header}</WidgetHeader>
          {/* One panel: the conversation and its composer belong together. */}
          <WidgetPanel className="flex flex-col overflow-hidden p-0">
            <div className="h-[480px]">{conversation}</div>
            <AnimatePresence>
              {connect.prompt && <div className="border-t border-border/70 p-2">{connect.prompt}</div>}
            </AnimatePresence>
            <div className="border-t border-border/70">{composer}</div>
          </WidgetPanel>
        </Widget>
      )}
    </AnimatePresence>
  )
}

function HeaderAction({
  label,
  ...props
}: React.ComponentProps<typeof Button> & { label: string }) {
  return (
    <Tooltip>
      <TooltipTrigger
        render={<Button variant="ghost" size="icon-sm" aria-label={label} className="text-muted-foreground" {...props} />}
      />
      <TooltipContent>{label}</TooltipContent>
    </Tooltip>
  )
}

/** An attached file, with its gist on hover when we know it. */
function FileChip({ name }: { name: string }) {
  const file = FILES[name as keyof typeof FILES]
  const chip = <AttachmentChip name={name} />
  return file ? <AttachmentPreview file={{ name, ...file }}>{chip}</AttachmentPreview> : chip
}

/**
 * Drives the docked ConnectPrompt: finds the open connectApp call, runs
 * ask → connecting → connected, answers the tool, and clears itself a
 * moment after it says what happens next.
 */
function useConnect(messages: ChatMessage[], answer: (toolCallId: string, connected: boolean) => void) {
  const part = messages
    .at(-1)
    ?.parts.find((p) => isToolUIPart(p) && getToolName(p) === "connectApp") as
    | Extract<ChatMessage["parts"][number], { type: "tool-connectApp" }>
    | undefined
  const [state, setState] = React.useState<ConnectState>("ask")
  const [shownFor, setShownFor] = React.useState<string | null>(null)

  const open = part?.state === "input-available"
  const id = part?.toolCallId ?? null

  React.useEffect(() => {
    if (state !== "connected" || !shownFor) return
    const t = window.setTimeout(() => setShownFor(null), 2600)
    return () => window.clearTimeout(t)
  }, [state, shownFor])

  const visible = id !== null && (open || (shownFor === id && state === "connected"))
  const prompt =
    visible && part?.input ? (
      <ConnectPrompt
        key={id}
        app={part.input.app ?? "Slack"}
        icon={<SlackMark />}
        reason={part.input.reason ?? ""}
        done={part.input.done}
        state={open ? state : "connected"}
        onConnect={() => {
          setState("connecting")
          setShownFor(id)
          window.setTimeout(() => {
            setState("connected")
            answer(id, true)
          }, 1100)
        }}
      />
    ) : null

  return { prompt, pending: open }
}

function SlackMark() {
  return (
    <svg viewBox="0 0 24 24" aria-hidden className="size-4">
      <path fill="#E01E5A" d="M5 15a2 2 0 1 1-2-2h2v2Zm1 0a2 2 0 1 1 4 0v5a2 2 0 1 1-4 0v-5Z" />
      <path fill="#36C5F0" d="M9 5a2 2 0 1 1 2-2v2H9Zm0 1a2 2 0 1 1 0 4H4a2 2 0 1 1 0-4h5Z" />
      <path fill="#2EB67D" d="M19 9a2 2 0 1 1 2 2h-2V9Zm-1 0a2 2 0 1 1-4 0V4a2 2 0 1 1 4 0v5Z" />
      <path fill="#ECB22E" d="M15 19a2 2 0 1 1-2 2v-2h2Zm0-1a2 2 0 1 1 0-4h5a2 2 0 1 1 0 4h-5Z" />
    </svg>
  )
}

/* Playground-only plumbing for scripted conversations. */
function useScriptedSession({
  autoStart,
  next,
  messages,
  busy,
  sendMessage,
  setMessages,
}: {
  autoStart: boolean
  next: ChatMessage | null
  messages: ChatMessage[]
  busy: boolean
  sendMessage: (m: ChatMessage) => Promise<void>
  setMessages: (fn: (prev: ChatMessage[]) => ChatMessage[]) => void
}) {
  // Start the scenario with its first scripted turn. Scheduled and cleared
  // on cleanup so StrictMode's mount → unmount → mount sends exactly once.
  React.useEffect(() => {
    if (!autoStart || messages.length > 0 || !next) return
    const t = window.setTimeout(() => void sendMessage(next), 0)
    return () => window.clearTimeout(t)
    // Only on mount.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  // See CHAINED_CONTINUATION_ID in scripts.ts.
  React.useEffect(() => {
    const last = messages.at(-1)
    if (busy || !last || last.id === CHAINED_CONTINUATION_ID) return
    if (!last.parts.some((p) => p.type === "tool-composeDraft")) return
    setMessages((prev) =>
      prev.map((m, i) => (i === prev.length - 1 ? { ...m, id: CHAINED_CONTINUATION_ID } : m))
    )
  }, [busy, messages, setMessages])
}

import type { UIMessage } from "ai"

import { createChat } from "@/lib/ai"
import type { Question } from "@/components/parts/ask-user"
import type { Draft } from "@/components/parts/draft-card"
import type { Finding } from "@/components/parts/findings"
import type { PlanStep } from "@/components/parts/plan"
import type { BarDatum } from "@/components/ds/bar-series"
import type { AiSpendModel, AiSpendPeriod } from "@/components/widgets/ai-spend"
import { BUDGET, MODELS as SPEND_MODELS, PERIODS } from "@/examples/ai-spend"

// Typed parts shared by the scripts and the renderer.
type Tools = {
  webSearch: {
    input: { query: string }
    output: { results: { title: string; url: string }[] }
  }
  askQuestions: {
    input: { questions: Question[] }
    output: { answers: Record<string, string> }
  }
  composeDraft: {
    input: Draft
    output: { status: "sent" | "discarded"; body?: string }
  }
  createIssues: {
    input: { tracker: string; issues: { title: string; owner: string }[] }
    output: { ids: string[] }
  }
  queryAnalytics: {
    input: { metric: string; range: string }
    output: { title: string; series: BarDatum[]; total: number; change: number; median: number; peak: number }
  }
  connectApp: {
    input: { app: "Slack"; reason: string; done: string }
    output: { connected: boolean }
  }
  reportSpend: {
    input: { period: string }
    output: { models: AiSpendModel[]; periods: AiSpendPeriod[]; budget: number }
  }
  readFile: {
    input: { name: string; pages: number }
    output: { title: string; findings: Finding[] }
  }
}
type Data = {
  plan: { title: string; steps: PlanStep[] }
}
export type ChatMessage = UIMessage<unknown, Data, Tools>

/* ---------------- Research: search → answer → sources ---------------- */

const research = createChat<ChatMessage>()
  .user("What shipped in the last Halden release?")
  .sleep(400)
  .assistant(({ writer }) => {
    writer.reasoning(
      "They want a summary of the latest release. I should read the changelog and the launch post, then group changes by impact."
    )
    writer.sleep(300)
    writer
      .tool("webSearch", { input: { query: "Halden 4.2 release notes" } })
      .sleep(1400)
      .output({
        results: [
          { title: "Halden 4.2 changelog", url: "https://halden.example/changelog/4-2" },
          { title: "Per-seat policies, explained", url: "https://blog.halden.example/per-seat-policies" },
          { title: "Audit log API reference", url: "https://docs.halden.example/api/audit-log" },
          { title: "API key rotation notice", url: "https://status.halden.example/notices/key-rotation" },
          { title: "Halden 4.1 changelog", url: "https://halden.example/changelog/4-1" },
          { title: "Roadmap: what's next after 4.2", url: "https://blog.halden.example/roadmap" },
        ],
      })
    writer.text(
      "Halden **4.2** is mostly about speed and control:\n\n- **Streaming exports.** Large CSV exports now stream instead of timing out, up to 2M rows.\n- **Per-seat policies.** Admins can set model and spend limits for each seat, not just per workspace.\n- **Audit log API.** Every policy change is now queryable, with a 400-day retention window.\n\nNothing is breaking. The only migration step is re-issuing API keys created before March, which now expire on rotation."
    )
    writer.sourceUrl({ sourceId: "s1", title: "Halden 4.2 changelog", url: "https://halden.example/changelog/4-2" })
    writer.sourceUrl({ sourceId: "s2", title: "Per-seat policies, explained", url: "https://blog.halden.example/per-seat-policies" })
    writer.sourceUrl({ sourceId: "s3", title: "Audit log API reference", url: "https://docs.halden.example/api/audit-log" })
    writer.sourceUrl({ sourceId: "s4", title: "API key rotation notice", url: "https://status.halden.example/notices/key-rotation" })
  })
  .user("Turn that into a checklist for the team")
  .sleep(400)
  .assistant(
    "| Owner | Task | When |\n| --- | --- | --- |\n| Platform | Re-issue pre-March API keys | Before rotation |\n| Admins | Set per-seat model limits | This sprint |\n| Data | Switch nightly export to streaming | Next deploy |\n| Security | Point SIEM at the audit log API | This month |\n\nWant me to turn these into tickets?"
  )
  .user("Yes, create the tickets")
  .sleep(400)
  .assistant(({ writer }) => {
    writer.text("Here are the four issues. I need your OK before I create them.")
    writer.tool("createIssues", {
      input: {
        tracker: "Linear",
        issues: [
          { title: "Re-issue pre-March API keys", owner: "Platform" },
          { title: "Set per-seat model limits", owner: "Admins" },
          { title: "Switch nightly export to streaming", owner: "Data" },
          { title: "Point SIEM at the audit log API", owner: "Security" },
        ],
      },
      needsApproval: true,
      output: { ids: ["HAL-201", "HAL-202", "HAL-203", "HAL-204"] },
    })
  })
  .assistant(({ writer, toolCall }) => {
    writer.sleep(300)
    writer.text(
      toolCall?.approved
        ? "Done. Each issue is assigned to its owner and linked back to this thread."
        : "Okay, I didn't create anything. The checklist is still above."
    )
  })

/* ------------- Draft: clarify → editable draft → send ------------- */

// The helper resolves a continuation by the id of the last scripted message
// it can find in the transcript, but continuations stream into the paused
// message (same id). A continuation that pauses again therefore needs its
// own id in the transcript; the playground renames the merged message to
// this id once it finishes (see useChainedContinuation). Real backends
// don't need this.
export const CHAINED_CONTINUATION_ID = "draft-reply"

const QUESTIONS: Question[] = [
  { id: "channel", question: "Which channel is this for?", choices: ["Email", "Blog post", "Social thread"] },
  { id: "tone", question: "What tone should it have?", choices: ["Friendly", "Formal", "Punchy"] },
]

type Channel = "Email" | "Blog post" | "Social thread"

const OPENERS: Record<string, string> = {
  Friendly: "Good news:",
  Formal: "We are pleased to announce that",
  Punchy: "It's here.",
}

// One draft per channel: its own fields, verbs and closing line. Tone only
// changes the opener, which is enough for a scripted demo.
function draftFor(channel: Channel, tone: string): Draft & { intro: string; done: string } {
  const open = OPENERS[tone] ?? OPENERS.Friendly
  if (channel === "Social thread") {
    return {
      kind: "New thread",
      app: "X",
      icon: "thread",
      title: "Launch thread",
      fields: [
        { label: "Account", value: "@halden-demo" },
        { label: "Network", value: "X" },
        { label: "Posts", value: "3" },
      ],
      summary: "@halden-demo · 3 posts",
      body: `1/ ${open} the new Halden dashboard is live.\n\n2/ Monitors, usage and spend on one screen. Loads twice as fast. Finally works on mobile.\n\n3/ Nothing changes about your data or alerts. Open it from the sidebar today.`,
      sendLabel: "Post thread",
      sentVerb: "Posted thread",
      intro: `Here is a ${tone.toLowerCase()} three-post thread for @halden-demo. Edit anything in place, then post it when it reads right.`,
      done: "Posted the thread from @halden-demo.",
    }
  }
  if (channel === "Blog post") {
    return {
      kind: "New blog post",
      app: "Blog",
      icon: "blog",
      title: "Meet the new dashboard",
      fields: [
        { label: "Blog", value: "blog.halden.example" },
        { label: "Title", value: "Meet the new dashboard" },
        { label: "Visibility", value: "Public" },
      ],
      summary: "blog.halden.example/new-dashboard",
      body: `${open} the new dashboard is live for every workspace.\n\nMonitors, usage and spend now share one screen, it loads twice as fast, and it finally works on mobile. Nothing changes about your data or alerts.\n\nOpen it from the sidebar and tell us what you think.`,
      sendLabel: "Publish post",
      sentVerb: "Published post",
      intro: `Here is a ${tone.toLowerCase()} blog post. Edit anything in place, then publish it when it reads right.`,
      done: "Published at blog.halden.example/new-dashboard.",
    }
  }
  return {
    kind: "New email",
    app: "Mail",
    icon: "mail",
    title: "Your new dashboard is live",
    fields: [
      { label: "From", value: "product@halden.example" },
      { label: "To", value: "Beta list · 1,284 people" },
      { label: "Subject", value: "Your new dashboard is live" },
    ],
    summary: "Beta list · 1,284 people",
    body: `Hi there,\n\n${open} the new dashboard is live. It brings your monitors, usage and spend onto one screen, loads twice as fast, and finally works on mobile.\n\nNothing changes about your data or alerts. Reply to this email if anything looks off. We read every message.\n\nThe Halden team`,
    sendLabel: "Send email",
    sentVerb: "Sent email",
    intro: `Here is a ${tone.toLowerCase()} email for the beta list. Edit anything in place, then send it when it reads right.`,
    done: "Sent to 1,284 people. Replies land in the product inbox.",
  }
}

const draft = createChat<ChatMessage>()
  .user("Draft a launch announcement for the new dashboard")
  .sleep(400)
  .assistant(({ writer }) => {
    writer.reasoning(
      "An announcement depends on the channel and the tone. Two questions now are cheaper than a rewrite later."
    )
    writer.sleep(300)
    writer.text("Two quick questions so I match the tone and length.")
    writer.tool("askQuestions", { input: { questions: QUESTIONS } })
  })
  .assistant(
    ({ writer, toolCall }) => {
      const answers =
        toolCall?.name === "askQuestions" ? toolCall.output?.answers : undefined
      // Respect the answer: an unknown or skipped channel falls back to email.
      const channel = (["Email", "Blog post", "Social thread"] as const).find(
        (c) => c === answers?.channel
      ) ?? "Email"
      const { intro, ...draft } = draftFor(channel, answers?.tone || "Friendly")
      writer.sleep(400)
      writer.text(intro)
      // `done` rides along in the input; the card ignores unknown keys.
      writer.tool("composeDraft", { input: draft })
    },
    { id: CHAINED_CONTINUATION_ID }
  )
  .assistant(({ writer, toolCall }) => {
    const draft = toolCall?.name === "composeDraft" ? toolCall.input : undefined
    const sent = toolCall?.name === "composeDraft" && toolCall.output?.status === "sent"
    const done = (draft as { done?: string } | undefined)?.done
    writer.sleep(300)
    writer.text(sent && done ? done : "Discarded. Nothing went out.")
  })

/* ------------------------------ Code ------------------------------ */

const DEBOUNCE_QUESTION: Question[] = [
  {
    id: "edge",
    question: "Which version do you want?",
